const wd="/home/scottdensmore/Developer/scottdensmore/my-first-commit";
const cmds=[
  ["git status", "git status --short --branch --untracked-files=all"],
  ["git remotes", "git remote -v"],
  ["git branches", "git branch --verbose --verbose --all"],
  ["recent commits", "git log --oneline --decorate -20"],
  ["planning files", "rg --files -g 'AGENTS.md' -g 'README.md' -g 'CHANGELOG.md' -g '*ROADMAP*' -g 'docs/**' -g 'package.json' -g '.github/workflows/**'"],
  ["markers", "rg -n \"TODO|FIXME|HACK|XXX|roadmap|Roadmap|future|Future|follow-up|follow up|known limitation|Known limitation\" app tests scripts docs README.md CHANGELOG.md package.json .github 2>/dev/null"]
];
const out=await Promise.all(cmds.map(async ([label,cmd])=>{
  const r=await tools.exec_command({cmd,workdir:wd,yield_time_ms:10000,max_output_tokens:12000});
  return `## ${label}\n${r.output}`;
}));
text(out.join("\n"));

