const wd="/home/scottdensmore/Developer/scottdensmore/my-first-commit";
const files=["README.md","docs/product.md","docs/architecture.md","docs/production.md","docs/manual-qa.md","docs/development.md","CHANGELOG.md","package.json","vitest.config.mts","playwright.config.ts",".github/dependabot.yml",".github/workflows/ci.yml",".github/workflows/deployed-smoke.yml",".github/workflows/promote-production-release.yml"];
const out=await Promise.all(files.map(async f=>{
 const r=await tools.exec_command({cmd:`sed -n '1,260p' ${f}`,workdir:wd,yield_time_ms:10000,max_output_tokens:20000});
 return `## ${f}\n${r.output}`;
}));
text(out.join("\n"));

